/bin/bash -lc "ls /tmp && npm root -g && python3 - <<'PY'
from html.parser import HTMLParser
from pathlib import Path
import json, re
s=Path('index.html').read_text()
class Validator(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.errors=[]
    def handle_starttag(self, tag, attrs):
        if tag not in {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr','path','circle'}: self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in {'path','circle'}: return
        if self.stack and self.stack[-1]==tag: self.stack.pop()
        else: self.errors.append((tag,self.stack[-3:]))
v=Validator(); v.feed(s)
print('HTML nesting:', v.errors or 'passed')
print('Unclosed elements:',v.stack)
json.loads(re.search(r'<script type=\"application/ld\\+json\">(.*?)</script>',s,re.S).group(1))
print('Recipe structured data: valid JSON')
print('Ingredient checkboxes:',len(re.findall(r'type=\"checkbox\"',s)))
print('Single file size:',len(s.encode()),'bytes')
print('Image embedded:', 'data:image/jpeg;base64,' in s)
PY"

